package android.os; import java.util.*; public class Handler {
 public final List<Runnable> immediate=new ArrayList<>(), delayed=new ArrayList<>();
 public void post(Runnable r){immediate.add(r);} public void postDelayed(Runnable r,long ms){delayed.add(r);}
 public void removeCallbacks(Runnable r){immediate.removeIf(x->x==r);delayed.removeIf(x->x==r);}
 public void flush(){while(!immediate.isEmpty())immediate.remove(0).run();}
}

