package android.view; import java.util.*; public class WindowManager {
 public final Set<View> windows=Collections.newSetFromMap(new IdentityHashMap<>());
 public boolean failNext; public int updates;
 public void addView(View v,LayoutParams p){if(failNext){failNext=false;throw new SecurityException("test rejection");}
  windows.add(v);v.attached=true;v.width=p.width>0?p.width:300;v.height=111;}
 public void removeView(View v){windows.remove(v);v.attached=false;}
