package com.nvu.operacional;
import android.content.SharedPreferences; import java.util.*;
final class FakePrefs implements SharedPreferences {
 final Map<String,Object> data=new HashMap<>(); boolean failCommit;
 public String getString(String k,String d){return data.get(k) instanceof String?(String)data.get(k):d;}
 public long getLong(String k,long d){return data.get(k) instanceof Number?((Number)data.get(k)).longValue():d;} public boolean contains(String k){return data.containsKey(k);} public int getInt(String k,int d){return data.get(k) instanceof Number?((Number)data.get(k)).intValue():d;}
 public boolean getBoolean(String k,boolean d){return data.get(k) instanceof Boolean?(Boolean)data.get(k):d;}
 public Editor edit(){return new Editor(){final Map<String,Object> pending=new HashMap<>();
  public Editor remove(String k){data.remove(k);return this;} public Editor putString(String k,String v){pending.put(k,v);return this;}
  public Editor putLong(String k,long v){pending.put(k,v);return this;} public Editor putInt(String k,int v){pending.put(k,v);return this;}
  public Editor putBoolean(String k,boolean v){pending.put(k,v);return this;}
  public boolean commit(){if(failCommit)return false;data.putAll(pending);return true;}
  public void apply(){data.putAll(pending);}
 };}
}
